import type { PluginUiLoader, PluginUiModule } from "@elaina/sdk/ui";

/**
 * Build-time registry of trusted plugin browser entries.
 *
 * `virtual:elaina-plugin-ui` is generated by the Vite plugin from workspace
 * `package.json` `elaina.ui` fields. The dynamic import keeps each plugin's panel
 * code out of the initial admin bundle.
 */
const loaders: Record<string, PluginUiLoader> = import.meta.glob(
	"../../../../plugins/*/src/ui.tsx",
) as Record<string, PluginUiLoader>;

export function pluginUiLoader(pluginId: string): PluginUiLoader | undefined {
	const entry = Object.entries(loaders).find(([path]) =>
		path.includes(`/plugins/${pluginId}/src/ui.tsx`),
	);
	if (entry === undefined) return undefined;
	return async () => {
		const module = (await entry[1]()) as
			| PluginUiModule
			| { readonly default: PluginUiModule["default"] };
		return { default: module.default };
	};
}
